Here is a simple program written in C++ to find the nth Fibonacci number using recursion:

```cpp
#include <iostream>
using namespace std;

int fibonacci(int n);

int main()
{
    cout << "Enter the number of Fibonacci terms to find: ";
    int n;
    cin >> n;
    cout << "The Fibonacci number at the " << n << "th term is: ";
    cout << fibonacci(n) << endl;
    return 0;
}

int fibonacci(int n)
{
    if (n == 0 || n == 1)
        return 1;
    else
        return fibonacci(n - 1) + fibonacci(n - 2);
}
```

